package uk.co.eggcraft.studioflow.language

import androidx.compose.runtime.compositionLocalOf

val LocalStudioLanguage = compositionLocalOf { "English" }

/**
 * Returns a [java.util.Locale] best matching the active app language.
 * Used by date/time/number formatters so chart axis labels, calendar headers,
 * month names etc. render in the user's language automatically.
 */
fun studioLocale(lang: String?): java.util.Locale {
    return when (normalizeLang(lang)) {
        "Türkçe" -> java.util.Locale("tr")
        "Deutsch" -> java.util.Locale.GERMAN
        "Français" -> java.util.Locale.FRENCH
        "Italiano" -> java.util.Locale.ITALIAN
        "Español (Spanish)" -> java.util.Locale("es")
        "Português" -> java.util.Locale("pt")
        "Русский (Russian)" -> java.util.Locale("ru")
        "日本語 (Japanese)" -> java.util.Locale.JAPANESE
        "中文 (Chinese)" -> java.util.Locale.CHINESE
        "العربية (Arabic)" -> java.util.Locale("ar")
        "हिन्दी (Hindi)" -> java.util.Locale("hi")
        else -> java.util.Locale.UK
    }
}

/**
 * Runtime translation lookup. Mirrors the Web `studioT` and Mac `t(...)` helpers.
 * Returns the English source if a translation is missing for the active language.
 */
fun studioT(text: String, lang: String?): String {
    val normalized = normalizeLang(lang)
    if (normalized == "English") return text
    return TRANSLATIONS[text]?.get(normalized) ?: text
}

internal fun normalizeLang(raw: String?): String {
    val cleaned = raw?.trim().orEmpty()
    if (cleaned.isEmpty()) return "English"
    return when (cleaned.lowercase()) {
        "tr", "tr-tr", "tr_tr", "turkce", "türkçe" -> "Türkçe"
        "de", "de-de", "deutsch", "german" -> "Deutsch"
        "fr", "fr-fr", "français", "francais", "french" -> "Français"
        "it", "it-it", "italiano", "italian" -> "Italiano"
        "es", "es-es", "espanol", "español", "español (spanish)", "spanish" -> "Español (Spanish)"
        "pt", "pt-pt", "pt-br", "portugues", "português", "portuguese" -> "Português"
        "ru", "ru-ru", "russian", "русский (russian)", "русский" -> "Русский (Russian)"
        "ja", "ja-jp", "japanese", "日本語 (japanese)", "日本語" -> "日本語 (Japanese)"
        "zh", "zh-cn", "chinese", "中文 (chinese)", "中文" -> "中文 (Chinese)"
        "ar", "ar-sa", "arabic", "العربية (arabic)", "العربية" -> "العربية (Arabic)"
        "hi", "hi-in", "hindi", "हिन्दी (hindi)", "हिन्दी" -> "हिन्दी (Hindi)"
        else -> cleaned
    }
}

